import{_ as e,o as n,c as i,ah as o}from"./chunks/framework.BcMkjLiY.js";const s="/projects/TonyPi/en/latest/assets/image2.BMUQlYkL.webp",a="/projects/TonyPi/en/latest/assets/image3.Dr38LNV2.webp",r="/projects/TonyPi/en/latest/assets/image4.BdsUFbP3.webp",l="/projects/TonyPi/en/latest/assets/image5.D7Xp7RU-.webp",g="/projects/TonyPi/en/latest/assets/image6.DfIa_C4o.webp",c="data:image/png;base64,",d="/projects/TonyPi/en/latest/assets/image8.iKsJ1XDW.webp",A="/projects/TonyPi/en/latest/assets/image9.LSrYTWhH.webp",h="/projects/TonyPi/en/latest/assets/image10.CNI4wbms.webp",m="/projects/TonyPi/en/latest/assets/image11.v4JEf8BE.webp",p="/projects/TonyPi/en/latest/assets/image12.Bq64QiLz.webp",y="/projects/TonyPi/en/latest/assets/image13.BTAxY_l8.webp",u="/projects/TonyPi/en/latest/assets/image14.lWbC1vxj.webp",b="/projects/TonyPi/en/latest/assets/image15.CKPsNyb2.webp",w="/projects/TonyPi/en/latest/assets/image16.C_v5kXV5.webp",x="data:image/png;base64,",U="data:image/png;base64,",C="data:image/png;base64,",f="/projects/TonyPi/en/latest/assets/image20.BocpTzxa.webp",q="/projects/TonyPi/en/latest/assets/image21.-wElpCwW.webp",I="data:image/png;base64,",k="data:image/png;base64,",T="data:image/png;base64,",E="/projects/TonyPi/en/latest/assets/image25.F74YNLsI.webp",B="/projects/TonyPi/en/latest/assets/image3.CQrngpS1.webp",R="/projects/TonyPi/en/latest/assets/image4.CfJ70xTH.webp",F="/projects/TonyPi/en/latest/assets/image5.Dv9XowZR.webp",V="/projects/TonyPi/en/latest/assets/image6.DtEMqSRt.webp",P="/projects/TonyPi/en/latest/assets/image7.DK9cxsdb.webp",v="data:image/png;base64,",D="data:image/png;base64,",z="/projects/TonyPi/en/latest/assets/image10.gQHsne3v.webp",G="/projects/TonyPi/en/latest/assets/image11.BjxSU-sB.webp",J=JSON.parse('{"title":"3. Remote Desktop Installation and Connection","description":"","frontmatter":{},"headers":[],"relativePath":"docs/6.remote.md","filePath":"docs/6.remote.md"}'),Q={name:"docs/6.remote.md"};function K(j,t,X,W,N,M){return n(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="_3-remote-desktop-installation-and-connection" tabindex="-1">3. Remote Desktop Installation and Connection <a class="header-anchor" href="#_3-remote-desktop-installation-and-connection" aria-label="Permalink to &quot;3. Remote Desktop Installation and Connection&quot;">​</a></h1><h2 id="_3-1-remote-desktop-installation-and-connection" tabindex="-1">3.1 Remote Desktop Installation and Connection <a class="header-anchor" href="#_3-1-remote-desktop-installation-and-connection" aria-label="Permalink to &quot;3.1 Remote Desktop Installation and Connection&quot;">​</a></h2><p>Prepare a computer. If you are using desktop computer, wireless network card is required.The network card should support 5G band.</p><h3 id="_3-1-1-preparation" tabindex="-1">3.1.1 Preparation <a class="header-anchor" href="#_3-1-1-preparation" aria-label="Permalink to &quot;3.1.1 Preparation&quot;">​</a></h3><ul><li><strong>Install VNC</strong></li></ul><p>VNC is a graphical remote desktop control software. Through connecting your computer to the WiFi generated by Raspberry Pi, you can control Raspberry Pi. Installation of VNC is as below.</p><p>(1) Double-click the installation program &quot;<strong><a href="https://store.hiwonder.com.cn/docs/common/Remote_connection_tool/VNC/VNC-Viewer-6.17.731-Windows.exe" target="_blank" rel="noreferrer">VNC-Viewer-6.17.731-Windows</a></strong>&quot; in the same directory as this section. Select the installation language as &quot;<strong>English</strong>&quot; and lick &quot;<strong>OK</strong>&quot;.</p><img loading="lazy" height="151" width="294" class="common_img" src="'+s+'"><p>(2) Click &quot;<strong>Next</strong>&quot;.</p><img loading="lazy" height="385" width="493" class="common_img" src="'+a+'"><p>(3) Tick &quot;<strong>I accept the terms in the License Agreement</strong>&quot;. Then click &quot;<strong>Next</strong>&quot;.</p><img loading="lazy" height="385" width="493" class="common_img" src="'+r+'"><p>(4) Remain default location where the software is installed. Click &quot;<strong>Next</strong>&quot; to proceed next interface. Then directly click &quot;<strong>Install</strong>&quot;.</p><img loading="lazy" height="385" width="493" class="common_img" src="'+l+'"><p>(5) When the installation completes, click &quot;<strong>Finish</strong>&quot;.</p><img loading="lazy" height="385" width="493" class="common_img" src="'+g+'"><p>(6) Click <img loading="lazy" height="69" width="69" src="'+c+'" style="width:45px;" alt="image"> to open VNC.</p><ul><li><strong>Start Robot</strong></li></ul><p>Start Robot When LED1 on expansion board starts flickering and buzzer emits one beep, robot boots up successfully.</p><h3 id="_3-1-2-connect-to-robot" tabindex="-1">3.1.2 Connect to Robot <a class="header-anchor" href="#_3-1-2-connect-to-robot" aria-label="Permalink to &quot;3.1.2 Connect to Robot&quot;">​</a></h3><p>(1) After turning Robot on successfully, the default mode is AP direct connection mode. Robot generates a WiFi starting with HW. Connect your computer to this WiFi.</p><img loading="lazy" height="58" width="361" src="'+d+'" alt="image" class="common_img"><p>(2) Input password. The password is &quot;<strong>hiwonder</strong>&quot;.</p><img loading="lazy" height="163" width="350" class="common_img" src="'+A+'" alt="image"><img loading="lazy" height="135" width="358" class="common_img" src="'+h+'" alt="image"><p>(3) After connection, open VNC Viewer. Input the default IP address of Raspberry Pi, <strong>192.168.149.1</strong>, and then press Enter. If you receive security warning, select &quot;<strong>Continue</strong>&quot;.</p><img loading="lazy" height="88" width="884" src="'+m+'" class="common_img" alt="image"><p>(4) Input username and password. (<strong>Username: pi;Password: raspberrypi</strong>). Click &quot;<strong>OK</strong>&quot; to enter Raspberry Pi desktop.</p><img loading="lazy" height="242" width="344" class="common_img" src="'+p+'"><p>(5) The desktop is as pictured. If black screen occurs or only cursor leaves on the screen, restart Raspberry Pi.</p><img loading="lazy" height="678" width="1266" class="common_img" src="'+y+'"><h3 id="_3-1-3-introduction-to-desktop" tabindex="-1">3.1.3 Introduction to Desktop <a class="header-anchor" href="#_3-1-3-introduction-to-desktop" aria-label="Permalink to &quot;3.1.3 Introduction to Desktop&quot;">​</a></h3><p>The desktop is as pictured after connecting Robot through VNC successfully.</p><img loading="lazy" height="731" width="1269" class="common_img" src="'+u+'"><p>The following table demonstrates common functions:</p><table class="docutils-nobg" border="1"><colgroup><col style="width:50%;"><col style="width:50%;"></colgroup><tbody><tr><td style="text-align:center;">Icon</td><td style="text-align:center;">Function</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="50" width="60" src="'+b+'" style="width:0.625in;height:0.52083in;" alt="2"></td><td style="text-align:left;"><p>Application menu. Click to select different applications.</p><p><img loading="lazy" height="310" width="176" src="'+w+'" style="width:0.80139in;height:1.41111in;"></p></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="49" width="54" src="'+x+'" style="width:0.62569in;height:0.56806in;" alt="3"></td><td style="text-align:left;">Browser.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="48" width="57" src="'+U+'" style="width:0.62569in;height:0.52708in;" alt="4"></td><td style="text-align:left;">File manager.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="41" width="60" src="'+C+'" style="width:0.625in;height:0.42708in;" alt="5"></td><td style="text-align:left;">LX terminal. Click to input command line in the opened interface.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="76" width="64" src="'+f+'" style="width:0.66667in;height:0.79167in;"></td><td style="text-align:left;">Trash. You can find the files deleted here.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="70" width="72" src="'+q+'" style="width:0.62569in;height:0.60833in;" alt=""></td><td style="text-align:left;">PC software. You can adjust pan tilt and adjust color threshold on it.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="41" width="29" src="'+I+'" style="width:0.30208in;height:0.42708in;" alt="8"></td><td style="text-align:left;">Full screen or exit full screen.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="34" width="34" src="'+k+'" style="width:0.35417in;height:0.35417in;" alt="9"></td><td style="text-align:left;">Exit full screen.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="41" width="32" src="'+T+'" style="width:0.35417in;height:0.45347in;" alt="10"></td><td style="text-align:left;"><p>Shut down, reboot and logout</p><p><img loading="lazy" height="157" width="300" src="'+E+'" style="width:2.28472in;height:1.19583in;"></p></td></tr></tbody></table><h2 id="_3-2-system-introduction" tabindex="-1">3.2 System Introduction <a class="header-anchor" href="#_3-2-system-introduction" aria-label="Permalink to &quot;3.2 System Introduction&quot;">​</a></h2><h3 id="_3-2-1-desktop-instruction" tabindex="-1">3.2.1 Desktop Instruction <a class="header-anchor" href="#_3-2-1-desktop-instruction" aria-label="Permalink to &quot;3.2.1 Desktop Instruction&quot;">​</a></h3><p>After remote connection via VNC, the Raspberry Pi system desktop is as shown in the figure below:</p><img loading="lazy" height="544" width="163" class="common_img" src="'+B+'"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Directory</strong></th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="84" width="70" src="'+R+'" style="width:0.72917in;height:0.875in;"></td><td style="text-align:center;">TonyPi PC software which includes action programming, debugging etc.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="107" width="116" src="'+F+'" style="width:1.20833in;height:1.11458in;"></td><td style="text-align:center;">Chinese-English switching tool.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="75" width="100" src="'+V+'" style="width:1.04167in;height:0.78125in;"></td><td style="text-align:center;">Color model parameter adjustment tool.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="93" width="95" src="'+P+'" style="width:0.98958in;height:0.96875in;"></td><td style="text-align:center;">Terminator terminal, which is used to input command to proceed operation.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="32" width="39" src="'+v+'" style="width:0.40625in;height:0.33333in;" alt="image"></td><td style="text-align:center;">File manager is a visual file directory interface.Recommended for beginner users who are not familiar with the command line.</td></tr></tbody></table><h3 id="_3-2-2-programming-instruction" tabindex="-1">3.2.2 Programming Instruction <a class="header-anchor" href="#_3-2-2-programming-instruction" aria-label="Permalink to &quot;3.2.2 Programming Instruction&quot;">​</a></h3><p>The input command must be case sensitive and space, and the keyword supports &quot;<strong>TAB</strong>&quot; key to fill.</p><p>(1) Click <img loading="lazy" height="28" width="40" src="'+D+'" style="width:0.41667in;height:0.29167in;"> icon and enter &quot;<strong>Is</strong>&quot; command and then press Enter to list all the documents. As shown in the figure below:</p><img loading="lazy" height="94" width="674" class="common_img" src="'+z+'"><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Directory</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">TonyPi</td><td style="text-align:center;">Store all the games and related program source code</td></tr><tr><td style="text-align:center;">TonyPi_PC_Software</td><td style="text-align:center;">TonyPi PC software source code (based on Qt)</td></tr><tr><td style="text-align:center;">hiwonder-toolbox</td><td style="text-align:center;">Wi-Fi management tool</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>For AI vision games, you only need to check the folder &quot;<strong>TonyPi</strong>&quot;.</p></div><p>(2) Enter <code>cd TonyPi</code> to open all the games and program source code. In the TonyPi, enter &quot;<strong>ls</strong>&quot; command in the following three main directories. As shown below:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TonyPi</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span></span></code></pre></div><img loading="lazy" height="111" width="665" class="common_img" src="'+G+'"><table tabindex="0"><thead><tr><th style="text-align:center;">Directory</th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">Functions</td><td style="text-align:center;">The directory where the AI vision game program is located.</td></tr><tr><td style="text-align:center;">TonyPi.py</td><td style="text-align:center;">Main program for running the games (auto-start has been set)</td></tr><tr><td style="text-align:center;">HiwonderSDK</td><td style="text-align:center;">Underlying file path (for hardware control)</td></tr></tbody></table><p>(3) Enter the <code>cd Functions</code> and &quot;<strong>ls</strong>&quot; instructions in turn again. Let&#39;s take a look at the corresponding games of the program:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Functions</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:center;">Program Name</th><th style="text-align:center;">Game</th></tr></thead><tbody><tr><td style="text-align:center;">RemoteControl.py</td><td style="text-align:center;">Model control (only for learning)</td></tr><tr><td style="text-align:center;">KickBall.py</td><td style="text-align:center;">Auto shooting</td></tr><tr><td style="text-align:center;">ColorDetect.py</td><td style="text-align:center;">Color recognition</td></tr><tr><td style="text-align:center;">VisualPatrol.py</td><td style="text-align:center;">Line follow</td></tr><tr><td style="text-align:center;">ColorTrack.py</td><td style="text-align:center;">Color recognition</td></tr><tr><td style="text-align:center;">FaceDetect.py</td><td style="text-align:center;">Facial recognition</td></tr><tr><td style="text-align:center;">ApriltagDetect.py</td><td style="text-align:center;">Tag recognition</td></tr></tbody></table><h3 id="_3-2-3-game-in-advanced-tutorial" tabindex="-1">3.2.3 Game in Advanced Tutorial <a class="header-anchor" href="#_3-2-3-game-in-advanced-tutorial" aria-label="Permalink to &quot;3.2.3 Game in Advanced Tutorial&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>You can go to &quot;<strong><a href="https://docs.hiwonder.com/projects/TonyPi/en/latest/docs/11.voice_interaction_and_intelligent_handling_course.html" target="_blank" rel="noreferrer">Intelligent Transport Course</a></strong>&quot; to learn the advanced tutorial.</p></div><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Program</strong></th><th style="text-align:center;"><strong>Game</strong></th></tr></thead><tbody><tr><td style="text-align:center;">Transport.py</td><td style="text-align:center;">Intelligent Handling</td></tr><tr><td style="text-align:center;">Follow.py</td><td style="text-align:center;">Object Tracking</td></tr></tbody></table>',59)])])}const H=e(Q,[["render",K]]);export{J as __pageData,H as default};
